// ── Product: immutable HTTP Request ─────────────────────────────────────
class HttpRequest {
  constructor({ url, method, headers, body, timeout, retries, auth }) {
    if (!url)    throw new Error('url is required');
    if (!method) throw new Error('method is required');

    this.url     = url;
    this.method  = method.toUpperCase();
    this.headers = Object.freeze({ ...headers });
    this.body    = body    ?? null;
    this.timeout = timeout ?? 5000;
    this.retries = retries ?? 0;
    this.auth    = auth    ?? null;

    Object.freeze(this);  // immutable — no mutation after construction
  }

  toString() {
    return `[${this.method}] ${this.url} (timeout:${this.timeout}ms, retries:${this.retries})`;
  }
}

// ── ConcreteBuilder ──────────────────────────────────────────────────────
class HttpRequestBuilder {
  #config;  // private — callers cannot touch raw config

  constructor(url) {
    // Sensible defaults — only url is required at construction time
    this.#config = {
      url,
      method:  'GET',
      headers: {},
      body:    null,
      timeout: 5000,
      retries: 0,
      auth:    null,
    };
  }

  // Each setter stores its value and returns `this` for chaining
  method(m)          { this.#config.method  = m;     return this; }
  body(b)            { this.#config.body    = b;     return this; }
  timeout(ms)        { this.#config.timeout = ms;    return this; }
  retry(n)           { this.#config.retries = n;     return this; }
  bearerAuth(token)  { this.#config.auth = `Bearer ${token}`; return this; }

  header(key, value) {
    this.#config.headers[key] = value;
    return this;
  }

  contentType(type)  { return this.header('Content-Type', type); }
  accept(type)       { return this.header('Accept', type); }

  // build() is the single validation gate — Product only exists if valid
  build() {
    const { method, body, timeout, url } = this.#config;

    if (!url)                          throw new Error('url is required');
    if (body && method === 'GET')      throw new Error('GET requests cannot have a body');
    if (timeout !== null && timeout < 0) throw new Error('timeout must be >= 0');

    // Clone config to prevent the caller retaining a mutable reference
    return new HttpRequest({ ...this.#config, headers: { ...this.#config.headers } });
  }

  // Optional: clone the builder for branching builds
  clone() {
    const copy = new HttpRequestBuilder(this.#config.url);
    copy.#config = { ...this.#config, headers: { ...this.#config.headers } };
    return copy;
  }
}

// ── Director: encodes common construction recipes ────────────────────────
class HttpRequestDirector {
  #builder;

  constructor(builder) { this.#builder = builder; }

  buildAuthenticatedPost(body, token) {
    return this.#builder
      .method('POST')
      .contentType('application/json')
      .accept('application/json')
      .body(JSON.stringify(body))
      .bearerAuth(token)
      .timeout(10_000)
      .retry(3)
      .build();
  }

  buildHealthCheck() {
    return this.#builder
      .method('GET')
      .accept('application/json')
      .timeout(2_000)
      .retry(1)
      .build();
  }
}

// ── Direct fluent usage ──────────────────────────────────────────────────
const getReq = new HttpRequestBuilder('https://api.example.com/users')
  .accept('application/json')
  .timeout(3_000)
  .build();

console.log(getReq.toString());
// [GET] https://api.example.com/users (timeout:3000ms, retries:0)

// ── Director usage ───────────────────────────────────────────────────────
const builder  = new HttpRequestBuilder('https://api.example.com/orders');
const director = new HttpRequestDirector(builder);
const postReq  = director.buildAuthenticatedPost({ item: 'book', qty: 2 }, 'tok_xyz');

console.log(postReq.toString());
// [POST] https://api.example.com/orders (timeout:10000ms, retries:3)
console.log(postReq.headers['Content-Type']); // application/json
console.log(postReq.auth);                    // Bearer tok_xyz

// ── Cross-field validation catches mistakes ──────────────────────────────
try {
  new HttpRequestBuilder('https://api.example.com/data')
    .method('GET')
    .body('this should fail')
    .build();
} catch (e) {
  console.log(e.message); // GET requests cannot have a body
}

// ── Branching: two variants from one base config ─────────────────────────
const base = new HttpRequestBuilder('https://api.example.com/report')
  .accept('application/json')
  .bearerAuth('tok_abc');

const jsonReq = base.clone().contentType('application/json').method('POST').body('{}').build();
const csvReq  = base.clone().accept('text/csv').build();

console.log(jsonReq.headers['Content-Type']); // application/json
console.log(csvReq.headers['Accept']);         // text/csv

// ── Real-world inspired: SQL Query Builder ───────────────────────────────
// Simplified version of how knex / TypeORM QueryBuilder work internally

class QueryBuilder {
  #state;

  constructor(tableName) {
    this.#state = {
      table:      tableName,
      columns:    ['*'],
      conditions: [],
      orderBy:    [],
      limitVal:   null,
      offsetVal:  null,
      joins:      [],
    };
  }

  select(...columns) {
    this.#state.columns = columns;
    return this;
  }

  where(condition) {
    this.#state.conditions.push(condition);
    return this;  // multiple .where() calls are ANDed together
  }

  join(table, on) {
    this.#state.joins.push(`JOIN ${table} ON ${on}`);
    return this;
  }

  orderBy(column, direction = 'ASC') {
    this.#state.orderBy.push(`${column} ${direction}`);
    return this;
  }

  limit(n) {
    if (n < 1) throw new Error('limit must be >= 1');
    this.#state.limitVal = n;
    return this;
  }

  offset(n) {
    if (n < 0) throw new Error('offset must be >= 0');
    this.#state.offsetVal = n;
    return this;
  }

  // build() produces the final SQL string (the 'Product')
  build() {
    const { table, columns, conditions, joins, orderBy, limitVal, offsetVal } = this.#state;

    if (!table) throw new Error('table is required');

    let sql = `SELECT ${columns.join(', ')} FROM ${table}`;

    if (joins.length)      sql += ' ' + joins.join(' ');
    if (conditions.length) sql += ' WHERE ' + conditions.join(' AND ');
    if (orderBy.length)    sql += ' ORDER BY ' + orderBy.join(', ');
    if (limitVal !== null) sql += ` LIMIT ${limitVal}`;
    if (offsetVal !== null) sql += ` OFFSET ${offsetVal}`;

    return sql;
  }
}

// ── Director: common query presets for the application ───────────────────
class UserQueryDirector {
  #qb;
  constructor(queryBuilder) { this.#qb = queryBuilder; }

  activeUsers() {
    return this.#qb
      .select('id', 'email', 'name', 'created_at')
      .where("status = 'active'")
      .orderBy('created_at', 'DESC')
      .build();
  }

  paginatedSearch(searchTerm, page = 1, pageSize = 20) {
    return this.#qb
      .select('id', 'email', 'name')
      .where(`name ILIKE '%${searchTerm}%'`)
      .orderBy('name')
      .limit(pageSize)
      .offset((page - 1) * pageSize)
      .build();
  }
}

// ── Direct fluent usage ──────────────────────────────────────────────────
const sql1 = new QueryBuilder('orders')
  .select('id', 'total', 'status')
  .join('customers', 'orders.customer_id = customers.id')
  .where("orders.status = 'pending'")
  .where('orders.total > 100')
  .orderBy('orders.created_at', 'DESC')
  .limit(50)
  .build();

console.log(sql1);
// SELECT id, total, status FROM orders
// JOIN customers ON orders.customer_id = customers.id
// WHERE orders.status = 'pending' AND orders.total > 100
// ORDER BY orders.created_at DESC LIMIT 50

// ── Director usage ───────────────────────────────────────────────────────
const director = new UserQueryDirector(new QueryBuilder('users'));

console.log(director.activeUsers());
// SELECT id, email, name, created_at FROM users
// WHERE status = 'active' ORDER BY created_at DESC

console.log(director.paginatedSearch('alice', 2, 10));
// SELECT id, email, name FROM users
// WHERE name ILIKE '%alice%' ORDER BY name LIMIT 10 OFFSET 10

// ── Validation: limit must be >= 1 ──────────────────────────────────────
try {
  new QueryBuilder('products').limit(-5).build();
} catch (e) {
  console.log(e.message); // limit must be >= 1
}
